"""SPO and Flag definitions for P9 result organization."""

from __future__ import annotations

from copy import deepcopy
from typing import Any


PHASE_ID = "P9"

SPO_SCHEMA = {
    "ordering_mode": {
        "description": "The selected result ordering strategy.",
        "source_actions": ["P9A1"],
    },
    "order_by_items": {
        "description": "The concrete ORDER BY items generated by P9A2.",
        "source_actions": ["P9A2"],
    },
    "pagination_policy": {
        "description": "The selected row/column pagination strategy.",
        "source_actions": ["P9A3"],
    },
    "pagination_values": {
        "description": "Concrete LIMIT/OFFSET/SLIMIT/SOFFSET values.",
        "source_actions": ["P9A4"],
    },
}

ACTION_TO_SPO_FIELD = {
    "P9A1": "ordering_mode",
    "P9A3": "pagination_policy",
}

FLAG_SCHEMA = {
    "has_ordering": {
        "description": "Whether the query has an explicit ORDER BY clause.",
        "source_actions": ["P9A1"],
    },
    "has_pagination": {
        "description": "Whether row or column pagination is enabled.",
        "source_actions": ["P9A3"],
    },
    "row_pagination": {
        "description": "Whether LIMIT is enabled.",
        "source_actions": ["P9A3"],
    },
    "column_pagination": {
        "description": "Whether SLIMIT is enabled.",
        "source_actions": ["P9A3"],
    },
    "result_organization_ready": {
        "description": "Whether ordering and pagination decisions are complete.",
        "source_actions": ["P9A3", "P9A4"],
    },
}


def has_spo_update(action_id: str) -> bool:
    return action_id in ACTION_TO_SPO_FIELD


def build_spo_delta(action_id: str, selected_action: str | None) -> dict:
    field = ACTION_TO_SPO_FIELD.get(action_id)
    return {PHASE_ID: {field: selected_action}} if field else {}


def has_flag_update(action_id: str) -> bool:
    return action_id in {"P9A1", "P9A3", "P9A4"}


def build_flag_delta(action_id: str, selected_action: str | None) -> dict:
    if action_id == "P9A1":
        return {"has_ordering": selected_action != "no_order"}
    if action_id == "P9A3":
        has_pagination = selected_action != "no_pagination"
        return {
            "has_pagination": has_pagination,
            "row_pagination": selected_action in {
                "row_limit",
                "row_limit_offset",
                "row_column_limit",
                "row_column_limit_offset",
            },
            "column_pagination": selected_action in {
                "column_limit",
                "column_limit_offset",
                "row_column_limit",
                "row_column_limit_offset",
            },
            "result_organization_ready": not has_pagination,
        }
    if action_id == "P9A4":
        return {"result_organization_ready": True}
    return {}


def build_phase_spo_delta(
    phase_spo: dict[str, Any],
    skill_outputs: list[dict[str, Any]],
) -> dict[str, Any]:
    order_by_items = phase_spo.get("order_by_items")
    pagination_values = phase_spo.get("pagination_values")
    for output in skill_outputs:
        query_frame_delta = output.get("query_frame_delta") or {}
        if output.get("action_id") == "P9A2" and "order_by" in query_frame_delta:
            order_by_items = deepcopy(query_frame_delta["order_by"])
        if output.get("action_id") == "P9A4":
            pagination_values = {
                key: deepcopy(query_frame_delta.get(key))
                for key in ("limit", "offset", "slimit", "soffset")
            }
    return {
        PHASE_ID: {
            "ordering_mode": phase_spo.get("ordering_mode"),
            "order_by_items": order_by_items,
            "pagination_policy": phase_spo.get("pagination_policy"),
            "pagination_values": pagination_values,
        }
    }
